select ok(not has_table_privilege('service_role','public.payment_history_source_objects','INSERT'),'worker has no direct provenance table grants');
select ok((select bool_and(relrowsecurity) from pg_class where relnamespace='public'::regnamespace and relkind='r' and relname like 'payment_history_%'),'all continuation tables enforce RLS');
create temp table transfer_context(key text primary key,value jsonb);
grant all on transfer_context to service_role;
