create function pg_temp.migration(op text,payload jsonb default '{}') returns jsonb language sql as $$select public.payment_history_migration_request_v1('10000000-0000-4000-8000-000000003019',op,payload,'30000000-0000-4000-8000-000000003019','40000000-0000-4000-8000-000000003019','sha256:'||repeat('a',64),7)->'result';$$;
