create function pg_temp.device(op text,payload jsonb default '{}') returns jsonb language sql as $$select public.payment_history_device_v1('10000000-0000-4000-8000-000000003019','20000000-0000-4000-8000-000000003019','30000000-0000-4000-8000-000000003019','60000000-0000-4000-8000-000000003019','sha256:'||repeat('b',64),'sha256:'||repeat('c',64),7,op,payload)->'result';$$;
create function pg_temp.analyse() returns jsonb language plpgsql as $$declare lease jsonb;f jsonb;begin
 select value into f from transfer_context where key='fixture';lease:=public.payment_history_migration_worker_v1('claim','{}')->'run';
 perform public.payment_history_migration_worker_v1('stage_objects',lease||jsonb_build_object('rows',f->'objects'));
 perform public.payment_history_migration_worker_v1('stage_movements',lease||jsonb_build_object('rows',f->'movements'));
 perform public.payment_history_migration_worker_v1('finish',lease||jsonb_build_object('raw_manifest',f->>'rawManifest','analysis_digest',repeat('d',64)));return lease;end;$$;
create function pg_temp.map_all(run uuid) returns void language plpgsql as $$declare scope_id text;begin
 for scope_id in select x->>'id' from jsonb_array_elements(pg_temp.migration('status',jsonb_build_object('run_id',run))->'scopes') x loop
  perform pg_temp.migration('mapping',jsonb_build_object('run_id',run,'local_scope_id',scope_id,'merchant_id','70000000-0000-4000-8000-000000003019','label','Synthetic explicitly matched merchant','reference','synthetic transfer mapping reference'));
 end loop;end;$$;
