select is((select value->>'deactivated' from transfer_context where key='cancel'),'5','undo retains ownership and deactivates the original five rows');
insert into transfer_context values('delta',pg_temp.device('delta_start',jsonb_build_object('dataset_id',(select value->>'dataset_id' from transfer_context where key='snapshot'),'revision','2','writer_epoch','2','page_size',100)));
insert into transfer_context values('delta_page',pg_temp.device('page',jsonb_build_object('cursor',(select value->>'cursor' from transfer_context where key='delta'))));
select is((select jsonb_array_length(value->'entities') from transfer_context where key='delta_page'),6,'undo propagates batch state and all five tombstones');
select is((select count(*) from transfer_context,jsonb_array_elements(value->'entities') x where key='delta_page' and x->>'kind'='movement' and x#>>'{payload,active}'='false'),5::bigint,'delta contains inactive versions rather than deleting financial provenance');
select is(pg_temp.cutover('freeze_web','{"writer_epoch":"2","complete_inventory":true,"reference":"synthetic rollback reconciliation"}')->>'reconciliation_required','true','rollback freezes web and demands reconciliation');
select throws_ok($$select pg_temp.device('local_write_grant','{"writer_epoch":"3","operation_id":"89000000-0000-4000-8000-000000003019","kind":"Undo"}')$$,'40001','payment_history_local_writer_closed','rollback never re-enables the old local writer');
set local role postgres;
select is((select count(*) from public.pos_sales where shop_id='10000000-0000-4000-8000-000000003019'),0::bigint,'historical transfer never creates native sales');
select is((select count(*) from public.payment_history_change_sets where shop_id='10000000-0000-4000-8000-000000003019' and revision=2 and change_count=0),1::bigint,'duplicate-only logical revision has an explicit empty marker');
update public.pos_sessions set status='revoked',revoked_at=clock_timestamp() where pos_session_id='60000000-0000-4000-8000-000000003019';
set local role service_role;
select throws_ok($$select pg_temp.device('authority')$$,'42501','payment_history_device_denied','revocation closes even an authority read');
select * from finish();
rollback;
